-- 0001_schema.sql
create extension if not exists pgcrypto;

create type staff_role as enum ('director', 'inventory', 'chef', 'staff', 'driver');
create type location_kind as enum ('kitchen', 'storage', 'site', 'vehicle');
create type movement_kind as enum ('receive', 'issue', 'return', 'loss', 'adjust', 'count', 'undo', 'transfer');

create table locations (
  id uuid primary key default gen_random_uuid(),
  name text not null unique check (length(trim(name)) between 1 and 80),
  kind location_kind not null default 'storage',
  active boolean not null default true,
  created_at timestamptz not null default now()
);

create table categories (
  name text primary key check (length(trim(name)) between 1 and 60),
  prefix text not null unique check (prefix ~ '^[A-Z]{2,5}$'),
  active boolean not null default true,
  created_at timestamptz not null default now()
);

create table staff (
  id uuid primary key default gen_random_uuid(),
  display_name text not null check (length(trim(display_name)) between 1 and 80),
  role staff_role not null,
  email text unique,
  auth_user_id uuid unique references auth.users (id),
  active boolean not null default true,
  created_at timestamptz not null default now(),
  created_by uuid references staff (id),

  check (role not in ('director', 'inventory') or email is not null)
);

create table staff_pins (
  staff_id uuid primary key references staff (id),
  pin_hash text not null,
  set_at timestamptz not null default now(),
  set_by uuid references staff (id)
);

create table pin_attempts (
  id bigserial primary key,
  staff_id uuid not null references staff (id),
  device_id uuid not null,
  ok boolean not null,
  at timestamptz not null default now()
);
create index pin_attempts_recent on pin_attempts (staff_id, at);

create table devices (
  id uuid primary key references auth.users (id),
  name text not null unique,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  created_by uuid references staff (id)
);

create table device_locations (
  device_id uuid not null references devices (id),
  location_id uuid not null references locations (id),
  primary key (device_id, location_id)
);

create table actor_sessions (
  id uuid primary key default gen_random_uuid(),
  token_hash text not null unique,
  staff_id uuid not null references staff (id),
  device_id uuid not null references devices (id),
  started_at timestamptz not null default now(),
  expires_at timestamptz not null,
  ended_at timestamptz
);

create table items (
  id uuid primary key default gen_random_uuid(),
  sku text not null unique check (sku ~ '^[A-Z0-9][A-Z0-9-]{1,31}$'),
  name text not null check (length(trim(name)) between 1 and 120),
  category text not null references categories (name),
  unit text not null check (length(trim(unit)) between 1 and 20),
  min_level numeric(12,3) not null default 0 check (min_level >= 0),
  par_level numeric(12,3) not null default 0 check (par_level >= 0),
  price numeric(12,2) not null default 0 check (price >= 0),
  supplier text,
  spot text,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  created_by uuid references staff (id),
  updated_at timestamptz
);
create index items_category_name on items (category, name);
create index items_name on items (lower(name));

create table item_codes (
  code text primary key check (length(code) between 3 and 64 and code !~* '^HK1:'),
  item_id uuid not null references items (id),
  pack_qty numeric(12,3) not null default 1 check (pack_qty > 0),
  label text,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  created_by uuid references staff (id)
);
create index item_codes_item on item_codes (item_id);

create table movements (
  id uuid primary key,
  item_id uuid not null references items (id),
  location_id uuid not null references locations (id),
  qty numeric(12,3) not null check (qty <> 0),
  kind movement_kind not null,
  reason text,
  note text check (note is null or length(note) <= 500),
  ref text,
  reverses uuid unique references movements (id),
  actor_id uuid not null references staff (id),
  device_id uuid references devices (id),
  session_user_id uuid not null,
  flag text,
  happened_at timestamptz not null,
  recorded_at timestamptz not null default now()
);
create index movements_item_time on movements (item_id, happened_at);
create index movements_time on movements (happened_at);
create index movements_kind_time on movements (kind, happened_at);
create index movements_actor_time on movements (actor_id, happened_at);
create index movements_location_item on movements (location_id, item_id);
create index movements_ref on movements (ref) where ref is not null;

create table stock_levels (
  item_id uuid not null references items (id),
  location_id uuid not null references locations (id),
  on_hand numeric(14,3) not null default 0,
  last_at timestamptz,
  primary key (item_id, location_id)
);

create table requests (
  id uuid primary key default gen_random_uuid(),
  number text not null unique,
  requested_by uuid not null references staff (id),
  status text not null check (status in ('pending','partial','fulfilled','received','denied','cancelled')),
  note text,
  decided_by uuid references staff (id),
  decided_note text,
  location_id uuid references locations (id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table request_lines (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null references requests (id),
  item_id uuid not null references items (id),
  qty_requested numeric(12,3) not null check (qty_requested > 0),
  qty_fulfilled numeric(12,3) not null default 0
);

create table losses (
  id uuid primary key default gen_random_uuid(),
  item_id uuid not null references items (id),
  location_id uuid not null references locations (id),
  qty numeric(12,3) not null check (qty > 0),
  reason text not null check (reason in ('spoiled','damaged','broken','expired','other')),
  note text,
  reported_by uuid not null references staff (id),
  status text not null check (status in ('pending','approved','denied')),
  decided_by uuid references staff (id),
  decided_note text,
  decided_at timestamptz,
  movement_id uuid references movements (id),
  created_at timestamptz not null default now()
);

create table counts (
  id uuid primary key default gen_random_uuid(),
  number text not null unique,
  location_id uuid not null references locations (id),
  category text references categories (name),
  status text not null check (status in ('open','submitted','cancelled')),
  note text,
  started_by uuid not null references staff (id),
  started_at timestamptz not null default now(),
  submitted_by uuid references staff (id),
  submitted_at timestamptz
);

create table count_lines (
  id uuid primary key default gen_random_uuid(),
  count_id uuid not null references counts (id),
  item_id uuid not null references items (id),
  expected numeric(14,3) not null,
  counted numeric(14,3),
  counted_by uuid references staff (id),
  counted_at timestamptz,
  applied numeric(14,3),
  unique (count_id, item_id)
);

create table audit_log (
  id bigserial primary key,
  at timestamptz not null default now(),
  actor_id uuid references staff (id),
  device_id uuid,
  session_user_id uuid,
  action text not null,
  entity text,
  entity_id text,
  detail jsonb not null default '{}'
);
create index audit_log_at on audit_log (at);

insert into locations (name, kind) values ('Main kitchen', 'kitchen');
insert into categories (name, prefix) values
  ('Dry Goods','DRY'), ('Produce','PRD'), ('Proteins','PRO'), ('Dairy','DAI'), ('Frozen','FRZ'),
  ('Beverages','BEV'), ('Bakery','BAK'), ('Cleaning','CLN'), ('Paper & Disposables','PPR'),
  ('Equipment','EQP'), ('Donation','DON'), ('Other','OTH');

create or replace function hk_schema_version() returns int language sql immutable as $$ select 1 $$;

select 'part 0001 applied' as proof, (select count(*) from categories) as categories, hk_schema_version() as version;

-- 0002_records_never_disappear.sql
create or replace function refuse_record_deletion() returns trigger
language plpgsql as $$
begin
  raise exception 'Records are never deleted. Deactivate, retire or cancel instead. (%)', tg_table_name
    using errcode = 'P0001';
end $$;

create or replace function refuse_record_edit() returns trigger
language plpgsql as $$
begin
  raise exception 'This record is permanent. Record a correction instead. (%)', tg_table_name
    using errcode = 'P0001';
end $$;

do $$
declare t text;
begin
  foreach t in array array['locations','categories','staff','staff_pins','pin_attempts','devices','device_locations',
    'actor_sessions','items','item_codes','movements','stock_levels','requests','request_lines','losses','counts',
    'count_lines','audit_log']
  loop
    execute format('create trigger %I before delete on %I for each row execute function refuse_record_deletion()', t || '_no_delete', t);
    execute format('create trigger %I before truncate on %I for each statement execute function refuse_record_deletion()', t || '_no_truncate', t);
  end loop;
  foreach t in array array['movements','audit_log','pin_attempts']
  loop
    execute format('create trigger %I before update on %I for each row execute function refuse_record_edit()', t || '_no_update', t);
  end loop;
end $$;

revoke all on function refuse_record_deletion() from public, anon, authenticated;
revoke all on function refuse_record_edit() from public, anon, authenticated;

create or replace function hk_schema_version() returns int language sql immutable as $$ select 2 $$;

select 'part 0002 applied' as proof,
  (select count(*) from pg_trigger where tgname like '%\_no\_delete') as delete_guards,
  hk_schema_version() as version;

-- 0003_stock_levels.sql
create or replace function movements_keep_stock() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform set_config('hk.stock_writer', 'on', true);
  insert into stock_levels (item_id, location_id, on_hand, last_at)
  values (new.item_id, new.location_id, new.qty, new.happened_at)
  on conflict (item_id, location_id) do update
    set on_hand = stock_levels.on_hand + excluded.on_hand,
        last_at = greatest(coalesce(stock_levels.last_at, excluded.last_at), excluded.last_at);
  perform set_config('hk.stock_writer', 'off', true);
  return new;
end $$;

create trigger movements_keep_stock after insert on movements
  for each row execute function movements_keep_stock();

create or replace function stock_levels_guard() returns trigger
language plpgsql as $$
begin
  if coalesce(current_setting('hk.stock_writer', true), 'off') <> 'on' then
    raise exception 'Stock comes only from movements.' using errcode = 'P0001';
  end if;
  return new;
end $$;

create trigger stock_levels_no_update before update on stock_levels
  for each row execute function stock_levels_guard();

create view stock with (security_invoker = true) as
  select i.*,
    coalesce((select sum(s.on_hand) from stock_levels s where s.item_id = i.id), 0) as on_hand,
    (select max(s.last_at) from stock_levels s where s.item_id = i.id) as last_moved,
    (select string_agg(c.code, ' ') from item_codes c where c.item_id = i.id and c.active) as codes
  from items i;

create or replace function verify_stock()
returns table (sku text, name text, location text, ledger numeric, cached numeric)
language sql stable security definer set search_path = public as $$
  with truth as (select item_id, location_id, sum(qty) as q from movements group by 1, 2)
  select i.sku, i.name, l.name, t.q, coalesce(s.on_hand, 0)
  from truth t join items i on i.id = t.item_id join locations l on l.id = t.location_id
  left join stock_levels s on s.item_id = t.item_id and s.location_id = t.location_id
  where t.q <> coalesce(s.on_hand, 0)
$$;

revoke all on function movements_keep_stock() from public, anon, authenticated;
revoke all on function stock_levels_guard() from public, anon, authenticated;
revoke all on function verify_stock() from public, anon, authenticated;

create or replace function hk_schema_version() returns int language sql immutable as $$ select 3 $$;

select 'part 0003 applied' as proof, hk_schema_version() as version;

-- 0004_roles_and_reading.sql
create or replace function me_staff() returns staff
language sql stable security definer set search_path = public as $$
  select s.* from staff s
  where s.auth_user_id = auth.uid() and s.active and s.role in ('director', 'inventory')
$$;

create or replace function is_manager() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from staff s where s.auth_user_id = auth.uid() and s.active and s.role in ('director', 'inventory'))
$$;

create or replace function is_director() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from staff s where s.auth_user_id = auth.uid() and s.active and s.role = 'director')
$$;

create or replace function is_device() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from devices d where d.id = auth.uid() and d.active)
$$;

create or replace function can_see_location(loc uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select is_manager() or exists (
    select 1 from device_locations dl join devices d on d.id = dl.device_id
    join locations l on l.id = dl.location_id
    where dl.device_id = auth.uid() and dl.location_id = loc and d.active and l.active)
$$;

create or replace function has_perm(r staff_role, perm text) returns boolean
language sql immutable as $$
  select case perm
    when 'view'          then true
    when 'loss_report'   then true
    when 'issue'         then r in ('director','inventory','chef','staff')
    when 'request'       then r in ('director','inventory','chef','staff')
    when 'count_entry'   then r in ('director','inventory','chef','staff')
    when 'receive'       then r in ('director','inventory')
    when 'adjust'        then r in ('director','inventory')
    when 'items_edit'    then r in ('director','inventory')
    when 'fulfil'        then r in ('director','inventory')
    when 'reports'       then r in ('director','inventory')
    when 'loss_decide'   then r = 'director'
    when 'people'        then r = 'director'
    else false end
$$;

alter table locations enable row level security;
alter table categories enable row level security;
alter table staff enable row level security;
alter table staff_pins enable row level security;
alter table pin_attempts enable row level security;
alter table devices enable row level security;
alter table device_locations enable row level security;
alter table actor_sessions enable row level security;
alter table items enable row level security;
alter table item_codes enable row level security;
alter table movements enable row level security;
alter table stock_levels enable row level security;
alter table requests enable row level security;
alter table request_lines enable row level security;
alter table losses enable row level security;
alter table counts enable row level security;
alter table count_lines enable row level security;
alter table audit_log enable row level security;

create policy locations_read on locations for select to authenticated using (is_manager() or can_see_location(id));
create policy categories_read on categories for select to authenticated using (is_manager() or is_device());
create policy items_read on items for select to authenticated using (is_manager() or is_device());
create policy item_codes_read on item_codes for select to authenticated using (is_manager() or is_device());
create policy stock_levels_read on stock_levels for select to authenticated using (can_see_location(location_id));
create policy movements_read on movements for select to authenticated using (can_see_location(location_id));
create policy staff_read on staff for select to authenticated using (is_manager());
create policy devices_read on devices for select to authenticated using (is_manager() or id = auth.uid());
create policy device_locations_read on device_locations for select to authenticated using (is_manager() or device_id = auth.uid());
create policy requests_read on requests for select to authenticated using (is_manager() or is_device());
create policy request_lines_read on request_lines for select to authenticated using (is_manager() or is_device());
create policy losses_read on losses for select to authenticated using (can_see_location(location_id));
create policy counts_read on counts for select to authenticated using (can_see_location(location_id));
create policy count_lines_read on count_lines for select to authenticated
  using (exists (select 1 from counts c where c.id = count_id and can_see_location(c.location_id)));
create policy audit_log_read on audit_log for select to authenticated using (is_director());

create or replace function tablet_roster()
returns table (id uuid, display_name text, role staff_role, has_pin boolean)
language sql stable security definer set search_path = public as $$
  select s.id, s.display_name, s.role, exists (select 1 from staff_pins p where p.staff_id = s.id)
  from staff s
  where s.active and (is_device() or is_manager())
  order by s.display_name
$$;

revoke all on function me_staff(), is_manager(), is_director(), is_device(), can_see_location(uuid), tablet_roster()
  from public, anon;
grant execute on function me_staff(), is_manager(), is_director(), is_device(), can_see_location(uuid), tablet_roster()
  to authenticated;
revoke all on function has_perm(staff_role, text) from public, anon;
grant execute on function has_perm(staff_role, text) to authenticated;

revoke insert, update, delete, truncate on all tables in schema public from anon, authenticated;
revoke all on staff_pins, pin_attempts, actor_sessions from anon, authenticated;

create or replace function hk_schema_version() returns int language sql immutable as $$ select 4 $$;

select 'part 0004 applied' as proof,
  (select count(*) from pg_tables where schemaname = 'public' and rowsecurity) as rls_tables,
  has_function_privilege('anon', 'tablet_roster()', 'execute') as anon_can_roster,
  hk_schema_version() as version;

-- 0005_doors.sql
create type door_result as (id uuid, duplicate boolean, refused boolean, reason text, flag text, here numeric, total numeric);

create or replace function stock_here(p_item uuid, p_location uuid) returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce((select on_hand from stock_levels where item_id = p_item and location_id = p_location), 0)
$$;

create or replace function stock_total(p_item uuid) returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce((select sum(on_hand) from stock_levels where item_id = p_item), 0)
$$;

create or replace function write_audit(p_actor uuid, p_device uuid, p_action text, p_entity text, p_entity_id text, p_detail jsonb)
returns void language sql security definer set search_path = public as $$
  insert into audit_log (actor_id, device_id, session_user_id, action, entity, entity_id, detail)
  values (p_actor, p_device, auth.uid(), p_action, p_entity, p_entity_id, coalesce(p_detail, '{}'))
$$;

create or replace function resolve_actor(p_token text, p_at timestamptz,
  out actor_id uuid, out actor_role staff_role, out device_id uuid, out problem text)
language plpgsql stable security definer set search_path = public as $$
declare m staff; s record;
begin
  if p_at is null or p_at > now() + interval '5 minutes' or p_at < now() - interval '24 hours' then
    problem := 'The scan time is off by more than allowed. Check the tablet clock.'; return;
  end if;
  select * into m from me_staff();
  if m.id is not null then actor_id := m.id; actor_role := m.role; return; end if;
  if not is_device() then problem := 'Sign in first.'; return; end if;
  device_id := auth.uid();
  if p_token is null or length(p_token) < 20 then problem := 'Tap your name and enter your PIN first.'; return; end if;
  select a.staff_id, st.role into s
  from actor_sessions a join staff st on st.id = a.staff_id
  where a.token_hash = encode(digest(p_token, 'sha256'), 'hex') and a.device_id = auth.uid() and st.active
    and p_at >= a.started_at - interval '5 minutes' and p_at <= coalesce(a.ended_at, a.expires_at);
  if not found then problem := 'Your sign-in on this tablet has ended. Enter your PIN again.'; return; end if;
  actor_id := s.staff_id; actor_role := s.role;
end $$;

create or replace function shortfall_decision(p_on_hand numeric, p_requested numeric, p_role staff_role, p_kind text,
  out decision text, out message text)
language sql immutable as $$
  select 'block'::text,
    format('Only %s on hand, so %s can''t come out. Count the shelf first.', trim_scale(p_on_hand), trim_scale(p_requested))
$$;

create or replace function refused(p_actor uuid, p_device uuid, p_action text, p_entity_id text, p_reason text)
returns door_result language plpgsql security definer set search_path = public as $$
begin
  perform write_audit(p_actor, p_device, 'refused.' || p_action, 'movements', p_entity_id, jsonb_build_object('reason', p_reason));
  return (null::uuid, false, true, p_reason, null::text, null::numeric, null::numeric)::door_result;
end $$;

create or replace function lock_level(p_item uuid, p_location uuid) returns numeric
language plpgsql security definer set search_path = public as $$
declare have numeric;
begin
  insert into stock_levels (item_id, location_id) values (p_item, p_location) on conflict do nothing;
  select on_hand into have from stock_levels where item_id = p_item and location_id = p_location for update;
  return have;
end $$;

create or replace function record_move(p_id uuid, p_token text, p_at timestamptz, p_item uuid, p_location uuid,
  p_kind text, p_qty numeric, p_reason text default null, p_note text default null, p_ref text default null)
returns door_result language plpgsql security definer set search_path = public as $$
declare a record; it items; ex movements; loc locations; delta numeric; have numeric; d record; perm text; fl text;
begin
  select * into ex from movements where id = p_id;
  if found then
    if ex.item_id = p_item and ex.location_id = p_location and ex.kind::text = p_kind then
      return (p_id, true, false, null, ex.flag, stock_here(p_item, p_location), stock_total(p_item))::door_result;
    end if;
    return refused(null, null, 'move', p_id::text, 'That scan id was already used for a different scan.');
  end if;
  select * into a from resolve_actor(p_token, p_at);
  if a.problem is not null then return refused(a.actor_id, a.device_id, 'move', p_item::text, a.problem); end if;
  if p_kind is null or p_kind not in ('receive', 'issue', 'return', 'adjust') then
    return refused(a.actor_id, a.device_id, 'move', p_item::text, 'Unknown movement type.');
  end if;
  perm := case p_kind when 'receive' then 'receive' when 'adjust' then 'adjust' else 'issue' end;
  if not has_perm(a.actor_role, perm) then
    return refused(a.actor_id, a.device_id, 'move', p_item::text, initcap(a.actor_role::text) || ' accounts can''t do that.');
  end if;
  select * into loc from locations where id = p_location;
  if not found or not loc.active or not can_see_location(p_location) then
    return refused(a.actor_id, a.device_id, 'move', p_item::text, 'This tablet can''t move stock at that location.');
  end if;
  select * into it from items where id = p_item;
  if not found or not it.active then return refused(a.actor_id, a.device_id, 'move', p_item::text, 'That item is not active.'); end if;
  if p_qty is null or p_qty = 0 then return refused(a.actor_id, a.device_id, 'move', p_item::text, 'Enter a quantity.'); end if;
  if p_kind <> 'adjust' and p_qty < 0 then return refused(a.actor_id, a.device_id, 'move', p_item::text, 'Enter the quantity as a positive number.'); end if;
  if p_kind = 'adjust' and coalesce(trim(p_note), '') = '' then return refused(a.actor_id, a.device_id, 'move', p_item::text, 'An adjustment needs a note saying why.'); end if;
  delta := case when p_kind = 'issue' then -p_qty else p_qty end;
  have := lock_level(p_item, p_location);
  if delta < 0 and have + delta < 0 then
    select * into d from shortfall_decision(have, -delta, a.actor_role, p_kind);
    if d.decision = 'block' then return refused(a.actor_id, a.device_id, 'move', p_item::text, d.message); end if;
    if d.decision = 'flag' then fl := d.message; end if;
  end if;
  insert into movements (id, item_id, location_id, qty, kind, reason, note, ref, actor_id, device_id, session_user_id, flag, happened_at)
  values (p_id, p_item, p_location, delta, p_kind::movement_kind, p_reason, p_note, p_ref, a.actor_id, a.device_id, auth.uid(), fl, p_at);
  perform write_audit(a.actor_id, a.device_id, 'stock.' || p_kind, 'movements', p_id::text,
    jsonb_build_object('sku', it.sku, 'qty', delta, 'location', p_location));
  return (p_id, false, false, null, fl, stock_here(p_item, p_location), stock_total(p_item))::door_result;
end $$;

create or replace function record_transfer(p_id uuid, p_id_in uuid, p_token text, p_at timestamptz, p_item uuid,
  p_from uuid, p_to uuid, p_qty numeric, p_note text default null)
returns door_result language plpgsql security definer set search_path = public as $$
declare a record; it items; lf locations; lt locations; have numeric; d record; fl text; r text;
begin
  if exists (select 1 from movements where id = p_id) then
    return (p_id, true, false, null, null, stock_here(p_item, p_from), stock_total(p_item))::door_result;
  end if;
  select * into a from resolve_actor(p_token, p_at);
  if a.problem is not null then return refused(a.actor_id, a.device_id, 'transfer', p_item::text, a.problem); end if;
  if not has_perm(a.actor_role, 'issue') then return refused(a.actor_id, a.device_id, 'transfer', p_item::text, 'This role can''t move stock.'); end if;
  if p_from = p_to then return refused(a.actor_id, a.device_id, 'transfer', p_item::text, 'Pick two different locations.'); end if;
  select * into lf from locations where id = p_from;
  select * into lt from locations where id = p_to;
  if lf.id is null or lt.id is null or not lf.active or not lt.active or not can_see_location(p_from) then
    return refused(a.actor_id, a.device_id, 'transfer', p_item::text, 'This tablet can''t move stock from there.');
  end if;
  select * into it from items where id = p_item;
  if not found or not it.active then return refused(a.actor_id, a.device_id, 'transfer', p_item::text, 'That item is not active.'); end if;
  if p_qty is null or p_qty <= 0 then return refused(a.actor_id, a.device_id, 'transfer', p_item::text, 'Enter how much is moving.'); end if;
  have := lock_level(p_item, p_from);
  if have - p_qty < 0 then
    select * into d from shortfall_decision(have, p_qty, a.actor_role, 'transfer');
    if d.decision = 'block' then return refused(a.actor_id, a.device_id, 'transfer', p_item::text, d.message); end if;
    if d.decision = 'flag' then fl := d.message; end if;
  end if;
  r := 'TRF-' || upper(substr(replace(p_id::text, '-', ''), 1, 8));
  insert into movements (id, item_id, location_id, qty, kind, reason, note, ref, actor_id, device_id, session_user_id, flag, happened_at) values
    (p_id, p_item, p_from, -p_qty, 'transfer', 'To ' || lt.name, p_note, r, a.actor_id, a.device_id, auth.uid(), fl, p_at),
    (p_id_in, p_item, p_to, p_qty, 'transfer', 'From ' || lf.name, p_note, r, a.actor_id, a.device_id, auth.uid(), null, p_at);
  perform write_audit(a.actor_id, a.device_id, 'stock.transfer', 'movements', p_id::text,
    jsonb_build_object('ref', r, 'qty', p_qty, 'from', p_from, 'to', p_to));
  return (p_id, false, false, null, fl, stock_here(p_item, p_from), stock_total(p_item))::door_result;
end $$;

create or replace function record_count(p_id uuid, p_token text, p_at timestamptz, p_item uuid, p_location uuid,
  p_counted numeric, p_note text default null)
returns door_result language plpgsql security definer set search_path = public as $$
declare a record; have numeric; delta numeric;
begin
  if exists (select 1 from movements where id = p_id) then
    return (p_id, true, false, null, null, stock_here(p_item, p_location), stock_total(p_item))::door_result;
  end if;
  select * into a from resolve_actor(p_token, p_at);
  if a.problem is not null then return refused(a.actor_id, a.device_id, 'count', p_item::text, a.problem); end if;
  if not has_perm(a.actor_role, 'adjust') then return refused(a.actor_id, a.device_id, 'count', p_item::text, 'Only an Inventory Manager or Director records a shelf count.'); end if;
  if not can_see_location(p_location) then return refused(a.actor_id, a.device_id, 'count', p_item::text, 'Not a location you can count.'); end if;
  if p_counted is null or p_counted < 0 then return refused(a.actor_id, a.device_id, 'count', p_item::text, 'Enter what is on the shelf (0 or more).'); end if;
  have := lock_level(p_item, p_location);
  delta := p_counted - have;
  if delta = 0 then
    perform write_audit(a.actor_id, a.device_id, 'stock.count_match', 'items', p_item::text, jsonb_build_object('counted', p_counted));
    return (null::uuid, false, false, 'Count matches.', null::text, have, stock_total(p_item))::door_result;
  end if;
  insert into movements (id, item_id, location_id, qty, kind, reason, note, actor_id, device_id, session_user_id, happened_at)
  values (p_id, p_item, p_location, delta, 'count', 'Shelf count', p_note, a.actor_id, a.device_id, auth.uid(), p_at);
  perform write_audit(a.actor_id, a.device_id, 'stock.count', 'movements', p_id::text, jsonb_build_object('counted', p_counted, 'delta', delta));
  return (p_id, false, false, null, null, stock_here(p_item, p_location), stock_total(p_item))::door_result;
end $$;

create or replace function undo_move(p_id uuid, p_token text, p_at timestamptz, p_target uuid)
returns door_result language plpgsql security definer set search_path = public as $$
declare a record; t movements; leg movements; first boolean := true;
begin
  if exists (select 1 from movements where id = p_id) then
    return (p_id, true, false, null, null, null, null)::door_result;
  end if;
  select * into a from resolve_actor(p_token, p_at);
  if a.problem is not null then return refused(a.actor_id, a.device_id, 'undo', p_target::text, a.problem); end if;
  if not has_perm(a.actor_role, 'issue') then return refused(a.actor_id, a.device_id, 'undo', p_target::text, 'This role can''t undo scans.'); end if;
  select * into t from movements where id = p_target;
  if not found or not can_see_location(t.location_id) then return refused(a.actor_id, a.device_id, 'undo', p_target::text, 'Movement not found.'); end if;
  if t.kind = 'undo' then return refused(a.actor_id, a.device_id, 'undo', p_target::text, 'An undo can''t be undone. Scan the item again instead.'); end if;
  if exists (select 1 from movements where reverses = p_target) then return refused(a.actor_id, a.device_id, 'undo', p_target::text, 'Already undone.'); end if;
  if not (a.actor_role in ('director', 'inventory') or (t.actor_id = a.actor_id and t.recorded_at > now() - interval '10 minutes')) then
    return refused(a.actor_id, a.device_id, 'undo', p_target::text, 'You can undo your own scans for 10 minutes. After that, ask an Inventory Manager.');
  end if;
  for leg in
    select * from movements m
    where (m.id = p_target or (t.kind = 'transfer' and m.kind = 'transfer' and m.ref = t.ref))
      and not exists (select 1 from movements u where u.reverses = m.id)
    order by (m.id = p_target) desc
  loop
    insert into movements (id, item_id, location_id, qty, kind, reason, ref, reverses, actor_id, device_id, session_user_id, happened_at)
    values (case when first then p_id else gen_random_uuid() end, leg.item_id, leg.location_id, -leg.qty, 'undo', 'Undo',
            leg.ref, leg.id, a.actor_id, a.device_id, auth.uid(), p_at);
    first := false;
  end loop;
  perform write_audit(a.actor_id, a.device_id, 'stock.undo', 'movements', p_id::text, jsonb_build_object('reverses', p_target));
  return (p_id, false, false, null, null, stock_here(t.item_id, t.location_id), stock_total(t.item_id))::door_result;
end $$;

create or replace function tablet_sign_in(p_staff uuid, p_pin text,
  out token text, out expires_at timestamptz, out display_name text, out role staff_role,
  out refused boolean, out locked boolean, out reason text)
language plpgsql security definer set search_path = public as $$
declare s staff; h text; fails int;
begin
  refused := true; locked := false;
  if not is_device() then reason := 'Only a kitchen tablet signs people in this way.'; return; end if;
  select * into s from staff where id = p_staff and active;
  if not found then reason := 'That person is not active.'; return; end if;
  select count(*) into fails from pin_attempts
    where staff_id = p_staff and not ok and at > now() - interval '15 minutes';
  if fails >= 5 then locked := true; reason := 'Too many wrong PINs. Wait 15 minutes or ask a Director.'; return; end if;
  select pin_hash into h from staff_pins where staff_id = p_staff;
  if h is null then reason := 'No PIN is set for this person yet. A Director sets it.'; return; end if;
  if p_pin is null or crypt(p_pin, h) <> h then
    insert into pin_attempts (staff_id, device_id, ok) values (p_staff, auth.uid(), false);
    perform write_audit(p_staff, auth.uid(), 'pin.wrong', 'staff', p_staff::text, '{}');
    reason := 'Wrong PIN.'; return;
  end if;
  insert into pin_attempts (staff_id, device_id, ok) values (p_staff, auth.uid(), true);
  token := encode(gen_random_bytes(24), 'hex');
  expires_at := now() + interval '12 hours';
  insert into actor_sessions (token_hash, staff_id, device_id, expires_at)
  values (encode(digest(token, 'sha256'), 'hex'), p_staff, auth.uid(), expires_at);
  perform write_audit(p_staff, auth.uid(), 'pin.sign_in', 'staff', p_staff::text, '{}');
  display_name := s.display_name; role := s.role; refused := false;
end $$;

create or replace function tablet_sign_out(p_token text) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  update actor_sessions set ended_at = now()
  where token_hash = encode(digest(p_token, 'sha256'), 'hex') and device_id = auth.uid() and ended_at is null;
  return found;
end $$;

create or replace function bootstrap_first_director(p_name text) returns uuid
language plpgsql security definer set search_path = public as $$
declare e text; new_id uuid;
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if exists (select 1 from staff) then raise exception 'Setup is already done.'; end if;
  select email into e from auth.users where id = auth.uid();
  insert into staff (display_name, role, email, auth_user_id) values (coalesce(nullif(trim(p_name), ''), e), 'director', lower(e), auth.uid())
  returning id into new_id;
  perform write_audit(new_id, null, 'setup.first_director', 'staff', new_id::text, '{}');
  return new_id;
end $$;

create or replace function claim_my_staff() returns boolean
language plpgsql security definer set search_path = public as $$
declare e text;
begin
  select lower(email) into e from auth.users where id = auth.uid();
  update staff set auth_user_id = auth.uid()
  where lower(email) = e and auth_user_id is null and active and role in ('director', 'inventory');
  return found or is_manager();
end $$;

create or replace function save_staff(p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare me staff; sid uuid := nullif(p->>'id', '')::uuid; r staff_role := (p->>'role')::staff_role;
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'people') then raise exception 'Only a Director manages people.'; end if;
  if sid is null then
    insert into staff (display_name, role, email, created_by)
    values (trim(p->>'display_name'), r, lower(nullif(trim(p->>'email'), '')), me.id) returning id into sid;
    perform write_audit(me.id, null, 'staff.added', 'staff', sid::text, jsonb_build_object('role', r));
  else
    if sid = me.id and (r <> 'director' or not coalesce((p->>'active')::boolean, true)) then
      raise exception 'You can''t remove your own Director access. Another Director has to.';
    end if;
    update staff set display_name = trim(p->>'display_name'), role = r, email = lower(nullif(trim(p->>'email'), '')),
      active = coalesce((p->>'active')::boolean, true) where id = sid;
    perform write_audit(me.id, null, 'staff.updated', 'staff', sid::text, jsonb_build_object('role', r, 'active', p->>'active'));
  end if;
  return sid;
end $$;

create or replace function set_pin(p_staff uuid, p_pin text) returns boolean
language plpgsql security definer set search_path = public as $$
declare me staff;
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'people') then raise exception 'Only a Director sets PINs.'; end if;
  if p_pin is null or p_pin !~ '^[0-9]{4,8}$' then raise exception 'A PIN is 4 to 8 digits.'; end if;
  insert into staff_pins (staff_id, pin_hash, set_by) values (p_staff, crypt(p_pin, gen_salt('bf', 8)), me.id)
  on conflict (staff_id) do update set pin_hash = excluded.pin_hash, set_at = now(), set_by = excluded.set_by;
  perform write_audit(me.id, null, 'pin.set', 'staff', p_staff::text, '{}');
  return true;
end $$;

create or replace function register_device(p_email text, p_name text, p_locations uuid[]) returns uuid
language plpgsql security definer set search_path = public as $$
declare me staff; uid uuid; l uuid;
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'people') then raise exception 'Only a Director adds tablets.'; end if;
  select id into uid from auth.users where lower(email) = lower(trim(p_email));
  if uid is null then raise exception 'No sign-in exists for %. Create it in Supabase Auth first.', p_email; end if;
  if exists (select 1 from staff where auth_user_id = uid) then raise exception 'That sign-in belongs to a person, not a tablet.'; end if;
  insert into devices (id, name, created_by) values (uid, trim(p_name), me.id)
  on conflict (id) do update set name = excluded.name, active = true;
  foreach l in array coalesce(p_locations, '{}') loop
    insert into device_locations (device_id, location_id) values (uid, l) on conflict do nothing;
  end loop;
  perform write_audit(me.id, null, 'device.registered', 'devices', uid::text, jsonb_build_object('name', p_name));
  return uid;
end $$;

create or replace function next_sku(p_category text) returns text
language sql stable security definer set search_path = public as $$
  select c.prefix || '-' || lpad((coalesce(max(nullif(regexp_replace(substr(i.sku, length(c.prefix) + 2), '\D', '', 'g'), '')::int), 0) + 1)::text, 4, '0')
  from categories c left join items i on i.sku like c.prefix || '-%'
  where c.name = p_category group by c.prefix
$$;

create or replace function save_item(p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare me staff; iid uuid := nullif(p->>'id', '')::uuid; v_sku text; v_cat text := coalesce(nullif(p->>'category', ''), 'Other');
  v_open numeric := nullif(p->>'opening', '')::numeric; v_loc uuid := nullif(p->>'location_id', '')::uuid;
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'items_edit') then raise exception 'Only an Inventory Manager or Director edits items.'; end if;
  if not exists (select 1 from categories where name = v_cat and active) then raise exception 'Category % doesn''t exist.', v_cat; end if;
  if iid is not null then
    update items set name = trim(p->>'name'), category = v_cat, unit = trim(p->>'unit'),
      min_level = coalesce(nullif(p->>'min_level', '')::numeric, 0), par_level = coalesce(nullif(p->>'par_level', '')::numeric, 0),
      price = coalesce(nullif(p->>'price', '')::numeric, 0), supplier = nullif(trim(p->>'supplier'), ''),
      spot = nullif(trim(p->>'spot'), ''), active = coalesce((p->>'active')::boolean, true), updated_at = now()
    where id = iid;
    perform write_audit(me.id, null, 'item.updated', 'items', iid::text, jsonb_build_object('name', p->>'name'));
    return iid;
  end if;
  v_sku := upper(coalesce(nullif(trim(p->>'sku'), ''), next_sku(v_cat)));
  insert into items (sku, name, category, unit, min_level, par_level, price, supplier, spot, created_by)
  values (v_sku, trim(p->>'name'), v_cat, coalesce(nullif(trim(p->>'unit'), ''), 'units'),
    coalesce(nullif(p->>'min_level', '')::numeric, 0), coalesce(nullif(p->>'par_level', '')::numeric, 0),
    coalesce(nullif(p->>'price', '')::numeric, 0), nullif(trim(p->>'supplier'), ''), nullif(trim(p->>'spot'), ''), me.id)
  returning id into iid;
  if nullif(trim(p->>'barcode'), '') is not null then
    insert into item_codes (code, item_id, pack_qty, label, created_by) values (trim(p->>'barcode'), iid, 1, 'Maker barcode', me.id);
  end if;
  if v_open is not null and v_open > 0 then
    if v_loc is null then select id into v_loc from locations where active order by created_at limit 1; end if;
    insert into movements (id, item_id, location_id, qty, kind, reason, actor_id, session_user_id, happened_at)
    values (gen_random_uuid(), iid, v_loc, v_open, 'count', 'Opening count', me.id, auth.uid(), now());
  end if;
  perform write_audit(me.id, null, 'item.created', 'items', iid::text, jsonb_build_object('sku', v_sku));
  return iid;
end $$;

create or replace function add_code(p_item uuid, p_code text, p_pack numeric default 1, p_label text default null) returns boolean
language plpgsql security definer set search_path = public as $$
declare me staff; other text;
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'items_edit') then raise exception 'Only an Inventory Manager or Director adds barcodes.'; end if;
  if p_code ~* '^HK1:' then raise exception 'That is one of our own labels. Scan the maker''s barcode instead.'; end if;
  select i.name into other from item_codes c join items i on i.id = c.item_id where c.code = trim(p_code);
  if other is not null then raise exception 'That barcode already belongs to %.', other; end if;
  if exists (select 1 from items where sku = upper(trim(p_code))) then raise exception 'That code is already a SKU.'; end if;
  insert into item_codes (code, item_id, pack_qty, label, created_by) values (trim(p_code), p_item, coalesce(p_pack, 1), p_label, me.id);
  perform write_audit(me.id, null, 'code.added', 'item_codes', trim(p_code), jsonb_build_object('item', p_item, 'pack', p_pack));
  return true;
end $$;

create or replace function set_code_active(p_code text, p_active boolean) returns boolean
language plpgsql security definer set search_path = public as $$
declare me staff;
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'items_edit') then raise exception 'Only an Inventory Manager or Director retires barcodes.'; end if;
  update item_codes set active = p_active where code = p_code;
  perform write_audit(me.id, null, case when p_active then 'code.restored' else 'code.retired' end, 'item_codes', p_code, '{}');
  return found;
end $$;

create or replace function save_location(p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare me staff; lid uuid := nullif(p->>'id', '')::uuid; act boolean := coalesce((p->>'active')::boolean, true);
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'items_edit') then raise exception 'Only an Inventory Manager or Director edits locations.'; end if;
  if lid is null then
    insert into locations (name, kind) values (trim(p->>'name'), coalesce(nullif(p->>'kind', ''), 'storage')::location_kind) returning id into lid;
  else
    if not act and exists (select 1 from stock_levels where location_id = lid and on_hand <> 0) then
      raise exception 'Stock is still recorded there. Move or count it to zero before closing.';
    end if;
    update locations set name = trim(p->>'name'), kind = coalesce(nullif(p->>'kind', ''), 'storage')::location_kind, active = act where id = lid;
  end if;
  perform write_audit(me.id, null, 'location.saved', 'locations', lid::text, p);
  return lid;
end $$;

revoke all on function stock_here(uuid, uuid), stock_total(uuid), write_audit(uuid, uuid, text, text, text, jsonb),
  resolve_actor(text, timestamptz), refused(uuid, uuid, text, text, text), lock_level(uuid, uuid)
  from public, anon, authenticated;
revoke all on function shortfall_decision(numeric, numeric, staff_role, text) from public, anon, authenticated;
revoke all on function
  record_move(uuid, text, timestamptz, uuid, uuid, text, numeric, text, text, text),
  record_transfer(uuid, uuid, text, timestamptz, uuid, uuid, uuid, numeric, text),
  record_count(uuid, text, timestamptz, uuid, uuid, numeric, text),
  undo_move(uuid, text, timestamptz, uuid),
  tablet_sign_in(uuid, text), tablet_sign_out(text),
  bootstrap_first_director(text), claim_my_staff(), save_staff(jsonb), set_pin(uuid, text),
  register_device(text, text, uuid[]), next_sku(text), save_item(jsonb), add_code(uuid, text, numeric, text),
  set_code_active(text, boolean), save_location(jsonb)
  from public, anon;
grant execute on function
  record_move(uuid, text, timestamptz, uuid, uuid, text, numeric, text, text, text),
  record_transfer(uuid, uuid, text, timestamptz, uuid, uuid, uuid, numeric, text),
  record_count(uuid, text, timestamptz, uuid, uuid, numeric, text),
  undo_move(uuid, text, timestamptz, uuid),
  tablet_sign_in(uuid, text), tablet_sign_out(text),
  bootstrap_first_director(text), claim_my_staff(), save_staff(jsonb), set_pin(uuid, text),
  register_device(text, text, uuid[]), next_sku(text), save_item(jsonb), add_code(uuid, text, numeric, text),
  set_code_active(text, boolean), save_location(jsonb)
  to authenticated;

create or replace function hk_schema_version() returns int language sql immutable as $$ select 5 $$;

select 'part 0005 applied' as proof,
  has_function_privilege('anon', 'record_move(uuid,text,timestamptz,uuid,uuid,text,numeric,text,text,text)', 'execute') as anon_can_move,
  has_function_privilege('authenticated', 'resolve_actor(text,timestamptz)', 'execute') as session_can_resolve,
  hk_schema_version() as version;

-- 0006_reading.sql
create or replace function facility_today() returns date
language sql stable as $$ select (now() at time zone 'America/Los_Angeles')::date $$;

create or replace function facility_midnight(d date) returns timestamptz
language sql stable as $$ select (d::timestamp) at time zone 'America/Los_Angeles' $$;

create or replace function lookup_code(p_code text, p_location uuid default null) returns jsonb
language plpgsql stable security invoker set search_path = public as $$
declare c text := trim(coalesce(p_code, '')); it record; cd item_codes;
begin
  if upper(c) like 'HK1:%' then c := substr(c, 5); end if;
  select s.*, (select on_hand from stock_levels l where l.item_id = s.id and l.location_id = p_location) as here
    into it from stock s where s.sku = upper(c);
  if found then return jsonb_build_object('found', true, 'item', to_jsonb(it), 'packQty', 1, 'via', 'sku'); end if;
  select * into cd from item_codes where code = c;
  if not found then return jsonb_build_object('found', false, 'code', c); end if;
  if not cd.active then return jsonb_build_object('found', false, 'code', c, 'retired', true); end if;
  select s.*, (select on_hand from stock_levels l where l.item_id = s.id and l.location_id = p_location) as here
    into it from stock s where s.id = cd.item_id;
  return jsonb_build_object('found', true, 'item', to_jsonb(it), 'packQty', cd.pack_qty, 'packLabel', cd.label, 'via', 'code');
end $$;

create or replace function item_search(p jsonb) returns jsonb
language plpgsql stable security invoker set search_path = public as $$
declare
  q text := nullif(trim(p->>'q'), '');
  st text := coalesce(p->>'state', 'active');
  loc uuid := nullif(p->>'location_id', '')::uuid;
  lim int := least(greatest(coalesce((p->>'limit')::int, 50), 1), 200);
  off int := greatest(coalesce((p->>'offset')::int, 0), 0);
  srt text := coalesce(p->>'sort', 'category');
  desc_ boolean := coalesce(p->>'dir', 'asc') = 'desc';
  words text[] := coalesce(regexp_split_to_array(q, '\s+'), '{}');
  total int; rows jsonb;
begin
  with base as (
    select s.*, coalesce((select on_hand from stock_levels l where l.item_id = s.id and l.location_id = loc), 0) as here
    from stock s
    where (case st
        when 'inactive' then not s.active
        when 'all' then true
        when 'low' then s.active and s.min_level > 0 and s.on_hand <= s.min_level and s.on_hand > 0
        when 'out' then s.active and s.on_hand <= 0
        when 'attention' then s.active and (s.on_hand <= 0 or (s.min_level > 0 and s.on_hand <= s.min_level))
        else s.active end)
      and (p->>'category' is null or p->>'category' = '' or s.category = p->>'category')
      and (not coalesce((p->>'only_here')::boolean, false)
           or exists (select 1 from stock_levels l where l.item_id = s.id and l.location_id = loc and l.on_hand <> 0))
      and (select bool_and(s.name ilike '%' || w || '%' or s.sku ilike '%' || w || '%'
                           or coalesce(s.codes, '') ilike '%' || w || '%' or coalesce(s.supplier, '') ilike '%' || w || '%')
           from unnest(words) w) is not false
  ),
  page as (
    select * from base
    order by
      case when not desc_ then case srt when 'name' then lower(name) when 'sku' then sku when 'category' then category || ' ' || lower(name) end end asc,
      case when desc_ then case srt when 'name' then lower(name) when 'sku' then sku when 'category' then category || ' ' || lower(name) end end desc,
      case when not desc_ then case srt when 'on_hand' then on_hand when 'here' then here when 'value' then greatest(on_hand, 0) * price when 'min_level' then min_level end end asc,
      case when desc_ then case srt when 'on_hand' then on_hand when 'here' then here when 'value' then greatest(on_hand, 0) * price when 'min_level' then min_level end end desc,
      case when not desc_ and srt = 'last_moved' then last_moved end asc nulls first,
      case when desc_ and srt = 'last_moved' then last_moved end desc nulls last,
      lower(name), id
    limit lim offset off
  )
  select (select count(*) from base), coalesce((select jsonb_agg(to_jsonb(page)) from page), '[]') into total, rows;
  return jsonb_build_object('rows', rows, 'total', total, 'offset', off, 'limit', lim);
end $$;

create or replace function item_detail(p_item uuid) returns jsonb
language sql stable security invoker set search_path = public as $$
  select to_jsonb(s) || jsonb_build_object(
    'levels', coalesce((select jsonb_agg(jsonb_build_object('id', l.id, 'name', l.name, 'kind', l.kind,
                 'on_hand', coalesce(sl.on_hand, 0), 'last_at', sl.last_at) order by l.created_at)
               from locations l left join stock_levels sl on sl.location_id = l.id and sl.item_id = s.id
               where l.active), '[]'),
    'code_list', coalesce((select jsonb_agg(to_jsonb(c) order by c.active desc, c.pack_qty) from item_codes c where c.item_id = s.id), '[]'),
    'pulled_30', coalesce((select -sum(m.qty) from movements m left join movements o on o.id = m.reverses
               where m.item_id = s.id and m.happened_at >= now() - interval '30 days'
                 and (case when m.kind = 'undo' then o.kind else m.kind end) = 'issue'), 0))
  from stock s where s.id = p_item
$$;

create or replace function movement_feed(p_location uuid default null, p_item uuid default null, p_limit int default 30)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(x order by x.happened_at desc), '[]') from (
    select m.id, m.kind, m.qty, m.reason, m.ref, m.flag, m.happened_at, m.reverses, i.sku, i.name as item_name, i.unit,
      st.display_name as person_name, l.name as location_name,
      exists (select 1 from movements u where u.reverses = m.id) as undone
    from movements m join items i on i.id = m.item_id join staff st on st.id = m.actor_id join locations l on l.id = m.location_id
    where can_see_location(m.location_id)
      and (p_location is null or m.location_id = p_location) and (p_item is null or m.item_id = p_item)
    order by m.happened_at desc limit least(greatest(coalesce(p_limit, 30), 1), 200)
  ) x
$$;

create or replace function dashboard(p_location uuid default null) returns jsonb
language sql stable security invoker set search_path = public as $$
  with today as (select facility_midnight(facility_today()) as since)
  select jsonb_build_object(
    'items', (select count(*) from items where active),
    'attention', (select count(*) from stock where active and (on_hand <= 0 or (min_level > 0 and on_hand <= min_level))),
    'value', (select coalesce(sum(greatest(on_hand, 0) * price), 0) from stock where active),
    'moves_today', (select count(*) from movements, today where happened_at >= today.since),
    'pulls_today', (select count(*) from movements m, today where m.kind = 'issue' and m.happened_at >= today.since
                    and not exists (select 1 from movements u where u.reverses = m.id)),
    'pull_cost_today', (select coalesce(sum(-m.qty * i.price), 0) from movements m join items i on i.id = m.item_id, today
                    where m.kind = 'issue' and m.happened_at >= today.since and not exists (select 1 from movements u where u.reverses = m.id)),
    'flagged_today', (select count(*) from movements, today where flag is not null and happened_at >= today.since),
    'low', coalesce((select jsonb_agg(to_jsonb(x)) from (
              select id, sku, name, unit, on_hand, min_level, par_level from stock
              where active and min_level > 0 and on_hand <= min_level order by on_hand / nullif(min_level, 0), name limit 12) x), '[]'))
$$;

create or replace function report_pulls(p jsonb) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  me staff; f timestamptz := nullif(p->>'from', '')::timestamptz; t timestamptz := nullif(p->>'to', '')::timestamptz;
  loc uuid := nullif(p->>'location_id', '')::uuid; who uuid := nullif(p->>'person_id', '')::uuid;
  lim int := least(greatest(coalesce((p->>'limit')::int, 100), 1), 1000); off int := greatest(coalesce((p->>'offset')::int, 0), 0);
  res jsonb;
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'reports') then raise exception 'Reports are for Inventory Managers and Directors.'; end if;
  with pulls as (
    select m.id, m.happened_at, i.sku, i.name, i.category, -m.qty as qty, i.unit, round(-m.qty * i.price, 2) as cost,
      m.reason, m.ref, st.display_name as person, l.name as location, m.flag
    from movements m join items i on i.id = m.item_id join staff st on st.id = m.actor_id join locations l on l.id = m.location_id
    where m.kind = 'issue' and not exists (select 1 from movements u where u.reverses = m.id)
      and (f is null or m.happened_at >= f) and (t is null or m.happened_at < t)
      and (loc is null or m.location_id = loc) and (who is null or m.actor_id = who)
      and (p->>'category' is null or p->>'category' = '' or i.category = p->>'category')
      and (p->>'reason' is null or p->>'reason' = '' or m.reason = p->>'reason')
  )
  select jsonb_build_object(
    'total', (select count(*) from pulls),
    'totals', jsonb_build_object('pulls', (select count(*) from pulls), 'cost', (select coalesce(sum(cost), 0) from pulls),
                                 'items', (select count(distinct sku) from pulls), 'people', (select count(distinct person) from pulls)),
    'by_person', coalesce((select jsonb_agg(x) from (select person as label, sum(cost) as value from pulls group by person order by 2 desc limit 10) x), '[]'),
    'rows', coalesce((select jsonb_agg(x) from (select * from pulls order by happened_at desc, id limit lim offset off) x), '[]'))
  into res;
  return res;
end $$;

create or replace function whoami() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'manager', (select jsonb_build_object('id', s.id, 'display_name', s.display_name, 'role', s.role, 'email', s.email)
                from staff s where s.auth_user_id = auth.uid() and s.active and s.role in ('director', 'inventory')),
    'device', (select jsonb_build_object('id', d.id, 'name', d.name) from devices d where d.id = auth.uid() and d.active),
    'locations', coalesce((select jsonb_agg(jsonb_build_object('id', l.id, 'name', l.name, 'kind', l.kind) order by l.created_at)
                 from locations l where l.active and can_see_location(l.id)), '[]'),
    'setup_needed', not exists (select 1 from staff))
$$;

revoke all on function facility_today(), facility_midnight(date) from public, anon;
grant execute on function facility_today(), facility_midnight(date) to authenticated;
revoke all on function lookup_code(text, uuid), item_search(jsonb), item_detail(uuid), movement_feed(uuid, uuid, int),
  dashboard(uuid), report_pulls(jsonb), whoami() from public, anon;
grant execute on function lookup_code(text, uuid), item_search(jsonb), item_detail(uuid), movement_feed(uuid, uuid, int),
  dashboard(uuid), report_pulls(jsonb), whoami() to authenticated;

create or replace function hk_schema_version() returns int language sql immutable as $$ select 6 $$;

select 'part 0006 applied' as proof,
  has_function_privilege('anon', 'item_search(jsonb)', 'execute') as anon_can_search,
  hk_schema_version() as version;

-- 0007_admin.sql
alter table device_locations add column active boolean not null default true;

create table pin_unlocks (
  id bigserial primary key,
  staff_id uuid not null references staff (id),
  by_staff uuid not null references staff (id),
  at timestamptz not null default now()
);

create table device_pairings (
  id uuid primary key default gen_random_uuid(),
  device_id uuid not null references devices (id),
  code_hash text not null unique,
  created_by uuid not null references staff (id),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  closed_at timestamptz,
  closed_how text check (closed_how in ('paired', 'replaced'))
);

alter table pin_unlocks enable row level security;
alter table device_pairings enable row level security;
revoke all on pin_unlocks, device_pairings from anon, authenticated;
revoke all on sequence pin_unlocks_id_seq from anon, authenticated;
create trigger pin_unlocks_no_delete before delete on pin_unlocks for each row execute function refuse_record_deletion();
create trigger pin_unlocks_no_truncate before truncate on pin_unlocks for each statement execute function refuse_record_deletion();
create trigger pin_unlocks_no_update before update on pin_unlocks for each row execute function refuse_record_edit();
create trigger device_pairings_no_delete before delete on device_pairings for each row execute function refuse_record_deletion();
create trigger device_pairings_no_truncate before truncate on device_pairings for each statement execute function refuse_record_deletion();

create or replace function can_see_location(loc uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select is_manager() or exists (
    select 1 from device_locations dl join devices d on d.id = dl.device_id
    join locations l on l.id = dl.location_id
    where dl.device_id = auth.uid() and dl.location_id = loc and dl.active and d.active and l.active)
$$;

create or replace function pin_fail_count(p_staff uuid) returns int
language sql stable security definer set search_path = public as $$
  select count(*)::int from pin_attempts a
  where a.staff_id = p_staff and not a.ok and a.at > greatest(
    now() - interval '15 minutes',
    coalesce((select max(x.at) from pin_attempts x where x.staff_id = p_staff and x.ok), '-infinity'),
    coalesce((select p.set_at from staff_pins p where p.staff_id = p_staff), '-infinity'),
    coalesce((select max(u.at) from pin_unlocks u where u.staff_id = p_staff), '-infinity'))
$$;

create or replace function tablet_sign_in(p_staff uuid, p_pin text,
  out token text, out expires_at timestamptz, out display_name text, out role staff_role,
  out refused boolean, out locked boolean, out reason text)
language plpgsql security definer set search_path = public as $$
declare s staff; h text;
begin
  refused := true; locked := false;
  if not is_device() then reason := 'Only a kitchen tablet signs people in this way.'; return; end if;
  select * into s from staff where id = p_staff and active;
  if not found then reason := 'That person is not active.'; return; end if;
  if pin_fail_count(p_staff) >= 5 then locked := true; reason := 'Too many wrong PINs. Wait 15 minutes or ask a Director to unlock you.'; return; end if;
  select pin_hash into h from staff_pins where staff_id = p_staff;
  if h is null then reason := 'No PIN is set for this person yet. A Director sets it.'; return; end if;
  if p_pin is null or crypt(p_pin, h) <> h then
    insert into pin_attempts (staff_id, device_id, ok) values (p_staff, auth.uid(), false);
    perform write_audit(p_staff, auth.uid(), 'pin.wrong', 'staff', p_staff::text, '{}');
    reason := 'Wrong PIN.'; return;
  end if;
  insert into pin_attempts (staff_id, device_id, ok) values (p_staff, auth.uid(), true);
  token := encode(gen_random_bytes(24), 'hex');
  expires_at := now() + interval '12 hours';
  insert into actor_sessions (token_hash, staff_id, device_id, expires_at)
  values (encode(digest(token, 'sha256'), 'hex'), p_staff, auth.uid(), expires_at);
  perform write_audit(p_staff, auth.uid(), 'pin.sign_in', 'staff', p_staff::text, '{}');
  display_name := s.display_name; role := s.role; refused := false;
end $$;

create or replace function unlock_pin(p_staff uuid) returns boolean
language plpgsql security definer set search_path = public as $$
declare me staff;
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'people') then raise exception 'Only a Director unlocks PINs.'; end if;
  insert into pin_unlocks (staff_id, by_staff) values (p_staff, me.id);
  perform write_audit(me.id, null, 'pin.unlocked', 'staff', p_staff::text, '{}');
  return true;
end $$;

create or replace function save_staff(p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  me staff; sid uuid := nullif(p->>'id', '')::uuid; r staff_role := nullif(p->>'role', '')::staff_role;
  nm text := trim(coalesce(p->>'display_name', '')); act boolean := coalesce((p->>'active')::boolean, true);
  em text := lower(nullif(trim(coalesce(p->>'email', '')), '')); pin text := nullif(trim(coalesce(p->>'pin', '')), '');
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'people') then raise exception 'Only a Director manages people.'; end if;
  if nm = '' or length(nm) > 80 then raise exception 'Type the person''s name (up to 80 letters).'; end if;
  if r is null then raise exception 'Pick a role.'; end if;
  if r not in ('director', 'inventory') then em := null; end if;
  if r in ('director', 'inventory') and em is null then raise exception 'A manager needs an email: it is how they sign in.'; end if;
  if em is not null and em !~ '^[^@\s]+@[^@\s]+$' then raise exception 'That email does not look right.'; end if;
  if em is not null and exists (select 1 from staff where lower(email) = em and id is distinct from sid) then
    raise exception 'Someone else already uses %.', em;
  end if;
  if act and exists (select 1 from staff where active and lower(display_name) = lower(nm) and id is distinct from sid) then
    raise exception 'Someone active is already called %. Add a last initial so the tablet tells them apart.', nm;
  end if;
  if pin is not null and pin !~ '^[0-9]{4,8}$' then raise exception 'A PIN is 4 to 8 digits.'; end if;
  if sid is null then
    insert into staff (display_name, role, email, active, created_by) values (nm, r, em, act, me.id) returning id into sid;
    perform write_audit(me.id, null, 'staff.added', 'staff', sid::text, jsonb_build_object('role', r));
  else
    if not exists (select 1 from staff where id = sid) then raise exception 'That person is not on the list.'; end if;
    if sid = me.id and (r <> 'director' or not act) then
      raise exception 'You can''t remove your own Director access. Another Director has to.';
    end if;
    update staff set display_name = nm, role = r, active = act,
      auth_user_id = case when email is distinct from em then null else auth_user_id end, email = em
    where id = sid;
    if not act then update actor_sessions set ended_at = now() where staff_id = sid and ended_at is null; end if;
    perform write_audit(me.id, null, 'staff.updated', 'staff', sid::text, jsonb_build_object('role', r, 'active', act));
  end if;
  if pin is not null then
    insert into staff_pins (staff_id, pin_hash, set_by) values (sid, crypt(pin, gen_salt('bf', 8)), me.id)
    on conflict (staff_id) do update set pin_hash = excluded.pin_hash, set_at = now(), set_by = excluded.set_by;
    perform write_audit(me.id, null, 'pin.set', 'staff', sid::text, '{}');
  end if;
  return sid;
end $$;

create or replace function people_list() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare me staff;
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'people') then raise exception 'Only a Director manages people.'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'id', s.id, 'display_name', s.display_name, 'role', s.role, 'email', s.email, 'active', s.active,
      'linked', s.auth_user_id is not null, 'is_me', s.id = me.id,
      'has_pin', p.staff_id is not null, 'pin_set_at', p.set_at, 'locked', pin_fail_count(s.id) >= 5,
      'on_tablet', exists (select 1 from actor_sessions a where a.staff_id = s.id and a.ended_at is null and a.expires_at > now()),
      'last_scan', (select max(m.recorded_at) from movements m where m.actor_id = s.id))
    order by s.active desc, s.display_name)
    from staff s left join staff_pins p on p.staff_id = s.id), '[]');
end $$;

create or replace function save_device(p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  me staff; did uuid := nullif(p->>'id', '')::uuid; act boolean := coalesce((p->>'active')::boolean, true);
  nm text := trim(coalesce(p->>'name', '')); locs uuid[];
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'people') then raise exception 'Only a Director manages tablets.'; end if;
  if did is null or not exists (select 1 from devices where id = did) then raise exception 'That tablet is not registered.'; end if;
  if nm = '' then raise exception 'Give the tablet a name.'; end if;
  if exists (select 1 from devices where lower(name) = lower(nm) and id <> did) then raise exception 'Another tablet is already called %.', nm; end if;
  select coalesce(array_agg(x::uuid), '{}') into locs from jsonb_array_elements_text(coalesce(p->'locations', '[]')) x;
  update devices set name = nm, active = act where id = did;
  update device_locations set active = (location_id = any(locs)) where device_id = did;
  insert into device_locations (device_id, location_id) select did, l from unnest(locs) l
  on conflict (device_id, location_id) do update set active = true;
  if not act then update actor_sessions set ended_at = now() where device_id = did and ended_at is null; end if;
  perform write_audit(me.id, null, 'device.saved', 'devices', did::text, jsonb_build_object('name', nm, 'active', act, 'locations', locs));
  return did;
end $$;

create or replace function tablet_list() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare me staff;
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'people') then raise exception 'Only a Director manages tablets.'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'id', d.id, 'name', d.name, 'active', d.active, 'email', u.email,
      'locations', coalesce((select jsonb_agg(dl.location_id) from device_locations dl where dl.device_id = d.id and dl.active), '[]'),
      'last_seen', (select max(m.recorded_at) from movements m where m.device_id = d.id),
      'people_on', (select count(*) from actor_sessions a where a.device_id = d.id and a.ended_at is null and a.expires_at > now()),
      'pairing_until', (select max(dp.expires_at) from device_pairings dp where dp.device_id = d.id and dp.closed_at is null and dp.expires_at > now()),
      'paired_at', (select max(dp.closed_at) from device_pairings dp where dp.device_id = d.id and dp.closed_how = 'paired'))
    order by d.active desc, d.name)
    from devices d left join auth.users u on u.id = d.id), '[]');
end $$;

create or replace function start_pairing(p_device uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  me staff; alpha text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; b bytea := gen_random_bytes(8);
  c text := ''; i int; exp timestamptz := now() + interval '15 minutes';
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'people') then raise exception 'Only a Director pairs tablets.'; end if;
  if not exists (select 1 from devices where id = p_device and active) then raise exception 'That tablet is switched off. Switch it on first.'; end if;
  for i in 0..7 loop c := c || substr(alpha, get_byte(b, i) % 32 + 1, 1); end loop;
  update device_pairings set closed_at = now(), closed_how = 'replaced' where device_id = p_device and closed_at is null;
  insert into device_pairings (device_id, code_hash, created_by, expires_at)
  values (p_device, encode(digest(c, 'sha256'), 'hex'), me.id, exp);
  perform write_audit(me.id, null, 'device.pairing_started', 'devices', p_device::text, '{}');
  return jsonb_build_object('code', c, 'expires_at', exp);
end $$;

create or replace function redeem_pairing(p_code text) returns table (device_id uuid, email text)
language plpgsql security definer set search_path = public as $$
#variable_conflict use_column
declare pr device_pairings;
  h text := encode(digest(upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g')), 'sha256'), 'hex');
begin
  select * into pr from device_pairings dp where dp.code_hash = h and dp.closed_at is null and dp.expires_at > now() for update;
  if not found or not exists (select 1 from devices d where d.id = pr.device_id and d.active) then return; end if;
  update device_pairings dp set closed_at = now(), closed_how = 'paired' where dp.id = pr.id;
  perform write_audit(null, pr.device_id, 'device.paired', 'devices', pr.device_id::text, '{}');
  return query select pr.device_id, u.email::text from auth.users u where u.id = pr.device_id;
end $$;

create or replace function save_location(p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare me staff; lid uuid := nullif(p->>'id', '')::uuid; act boolean := coalesce((p->>'active')::boolean, true);
  nm text := trim(coalesce(p->>'name', ''));
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'items_edit') then raise exception 'Only an Inventory Manager or Director edits locations.'; end if;
  if nm = '' or length(nm) > 80 then raise exception 'Give the location a name (up to 80 letters).'; end if;
  if exists (select 1 from locations where lower(name) = lower(nm) and id is distinct from lid) then
    raise exception 'There is already a location called %.', nm;
  end if;
  if lid is null then
    insert into locations (name, kind) values (nm, coalesce(nullif(p->>'kind', ''), 'storage')::location_kind) returning id into lid;
  else
    if not act and exists (select 1 from stock_levels where location_id = lid and on_hand <> 0) then
      raise exception 'Stock is still recorded there. Move or count it to zero before closing.';
    end if;
    update locations set name = nm, kind = coalesce(nullif(p->>'kind', ''), 'storage')::location_kind, active = act where id = lid;
  end if;
  perform write_audit(me.id, null, 'location.saved', 'locations', lid::text, p);
  return lid;
end $$;

create or replace function location_list() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not is_manager() then raise exception 'Only a manager sees every location.'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'id', l.id, 'name', l.name, 'kind', l.kind, 'active', l.active,
      'stocked', (select count(*) from stock_levels sl where sl.location_id = l.id and sl.on_hand <> 0),
      'tablets', (select count(*) from device_locations dl join devices d on d.id = dl.device_id
                  where dl.location_id = l.id and dl.active and d.active))
    order by l.active desc, l.created_at) from locations l), '[]');
end $$;

create or replace function save_category(p jsonb) returns text
language plpgsql security definer set search_path = public as $$
declare me staff; orig text := nullif(trim(coalesce(p->>'original', '')), '');
  nm text := trim(coalesce(p->>'name', '')); px text := upper(trim(coalesce(p->>'prefix', '')));
  act boolean := coalesce((p->>'active')::boolean, true);
begin
  select * into me from me_staff();
  if me.id is null or not has_perm(me.role, 'items_edit') then raise exception 'Only an Inventory Manager or Director edits categories.'; end if;
  if nm = '' or length(nm) > 60 then raise exception 'Give the category a name (up to 60 letters).'; end if;
  if px !~ '^[A-Z]{2,5}$' then raise exception 'A prefix is 2 to 5 capital letters, like DRY.'; end if;
  if exists (select 1 from categories where prefix = px and name is distinct from orig) then raise exception 'The prefix % is already used.', px; end if;
  if exists (select 1 from categories where lower(name) = lower(nm) and name is distinct from orig) then
    raise exception 'There is already a category called %.', nm;
  end if;
  if orig is null then
    insert into categories (name, prefix, active) values (nm, px, act);
  else
    if not exists (select 1 from categories where name = orig) then raise exception 'That category is not on the list.'; end if;
    if nm <> orig and exists (select 1 from items where category = orig) then
      raise exception 'Items already use the name %, so it stays. You can still change its prefix or switch it off.', orig;
    end if;
    update categories set name = nm, prefix = px, active = act where name = orig;
  end if;
  perform write_audit(me.id, null, 'category.saved', 'categories', nm, p);
  return nm;
end $$;

create or replace function category_list() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not is_manager() then raise exception 'Only a manager edits categories.'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'name', c.name, 'prefix', c.prefix, 'active', c.active,
      'items', (select count(*) from items i where i.category = c.name), 'next_sku', next_sku(c.name))
    order by c.active desc, c.name) from categories c), '[]');
end $$;

create or replace function category_names() returns setof text
language sql stable set search_path = public as $$ select name from categories where active order by name $$;

revoke all on function pin_fail_count(uuid) from public, anon, authenticated;
revoke all on function redeem_pairing(text) from public, anon, authenticated;
grant execute on function redeem_pairing(text) to service_role;
revoke all on function unlock_pin(uuid), people_list(), save_device(jsonb), tablet_list(), start_pairing(uuid),
  location_list(), save_category(jsonb), category_list(), category_names() from public, anon;
grant execute on function unlock_pin(uuid), people_list(), save_device(jsonb), tablet_list(), start_pairing(uuid),
  location_list(), save_category(jsonb), category_list(), category_names() to authenticated;

create or replace function hk_schema_version() returns int language sql immutable as $$ select 7 $$;

select 'part 0007 applied' as proof,
  has_function_privilege('authenticated', 'redeem_pairing(text)', 'execute') as session_can_redeem,
  has_function_privilege('anon', 'start_pairing(uuid)', 'execute') as anon_can_pair,
  hk_schema_version() as version;

-- 0008_search_path_extensions.sql
do $$
declare f record;
begin
  for f in
    select p.oid::regprocedure as sig
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proconfig @> array['search_path=public']
  loop
    execute format('alter function %s set search_path = public, extensions', f.sig);
  end loop;
end $$;

create or replace function hk_schema_version() returns int language sql immutable as $$ select 8 $$;

select 'part 0008 applied' as proof,
  (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proconfig @> array['search_path=public']) as still_public_only,
  hk_schema_version() as version;

-- 0009_input_hygiene.sql
create or replace function hk_clean_line(t text, max_len int) returns boolean
language sql immutable set search_path = public, extensions as $$
  select t is null or (length(t) <= max_len
    and t !~ '[\x01-\x1F\x7F-\x9F]'
    and t !~ '[​‪-‮⁦-⁩﻿]')
$$;

create or replace function hk_clean_note(t text, max_len int) returns boolean
language sql immutable set search_path = public, extensions as $$
  select t is null or (length(t) <= max_len
    and t !~ '[\x01-\x08\x0B\x0C\x0E-\x1F\x7F-\x9F]'
    and t !~ '[​‪-‮⁦-⁩﻿]')
$$;

alter table staff      add constraint staff_name_clean      check (hk_clean_line(display_name, 80));
alter table staff      add constraint staff_email_clean     check (email is null or (hk_clean_line(email, 254) and email = lower(email) and email ~ '^[^@\s]+@[^@\s]+$'));
alter table devices    add constraint devices_name_clean    check (hk_clean_line(name, 80) and length(trim(name)) >= 1);
alter table locations  add constraint locations_name_clean  check (hk_clean_line(name, 80));
alter table categories add constraint categories_name_clean check (hk_clean_line(name, 60));
alter table items      add constraint items_text_clean      check (hk_clean_line(name, 120) and hk_clean_line(unit, 20)
                                                               and hk_clean_line(spot, 60) and hk_clean_line(supplier, 120));
alter table item_codes add constraint item_codes_clean      check (code ~ '^[\x21-\x7E]{3,64}$' and hk_clean_line(label, 80));
alter table movements  add constraint movements_text_clean  check (hk_clean_line(reason, 120) and hk_clean_line(ref, 40) and hk_clean_note(note, 500));
alter table counts     add constraint counts_note_clean     check (hk_clean_note(note, 500));
alter table losses     add constraint losses_notes_clean    check (hk_clean_note(note, 500) and hk_clean_note(decided_note, 500));
alter table requests   add constraint requests_notes_clean  check (hk_clean_note(note, 500) and hk_clean_note(decided_note, 500));

revoke all on function hk_clean_line(text, int), hk_clean_note(text, int) from public, anon;
grant execute on function hk_clean_line(text, int), hk_clean_note(text, int) to authenticated;

create or replace function hk_schema_version() returns int language sql immutable set search_path = public, extensions as $$ select 9 $$;

select 'part 0009 applied' as proof,
  (select count(*) from pg_constraint where conname like '%\_clean' and connamespace = 'public'::regnamespace) as clean_checks,
  hk_schema_version() as version;

-- security check, inside the same transaction: if it fails, nothing above is kept
do $check$
declare
  bad text[] := '{}';
  r record;
  internal text[] := array['refuse_record_deletion','refuse_record_edit','stock_levels_guard','movements_keep_stock',
    'stock_here','stock_total','shortfall_decision','write_audit','resolve_actor','refused','lock_level',
    'pin_fail_count','redeem_pairing','verify_stock'];
  secret text[] := array['staff_pins','pin_attempts','actor_sessions','pin_unlocks','device_pairings'];
begin
  for r in select c.relname from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and not c.relrowsecurity loop
    bad := bad || format('1. RLS is off on table %s', r.relname);
  end loop;
  for r in select tablename, policyname, cmd from pg_policies where schemaname = 'public' and cmd <> 'SELECT' loop
    bad := bad || format('2. policy %s on %s allows %s', r.policyname, r.tablename, r.cmd);
  end loop;
  for r in select p.oid::regprocedure::text as f from pg_proc p
           where p.pronamespace = 'public'::regnamespace and p.proname <> 'hk_schema_version'
             and has_function_privilege('anon', p.oid, 'execute') loop
    bad := bad || format('3. signed-out visitors can run %s', r.f);
  end loop;
  for r in select p.oid::regprocedure::text as f from pg_proc p
           where p.pronamespace = 'public'::regnamespace and p.proname = any(internal)
             and has_function_privilege('authenticated', p.oid, 'execute') loop
    bad := bad || format('4. signed-in sessions can run internal %s', r.f);
  end loop;
  if to_regprocedure('public.redeem_pairing(text)') is null
     or not has_function_privilege('service_role', 'public.redeem_pairing(text)', 'execute') then
    bad := bad || '5. the service role cannot redeem pairing codes'::text;
  end if;
  for r in select c.relname, x.role, p.priv from pg_class c
           cross join (values ('anon'), ('authenticated')) x(role)
           cross join unnest(array['INSERT','UPDATE','DELETE','TRUNCATE']) p(priv)
           where c.relnamespace = 'public'::regnamespace and c.relkind = 'r'
             and has_table_privilege(x.role, c.oid, p.priv) loop
    bad := bad || format('6. %s can %s table %s directly', r.role, r.priv, r.relname);
  end loop;
  for r in select t, x.role from unnest(secret) t cross join (values ('anon'), ('authenticated')) x(role)
           where to_regclass('public.' || t) is not null and has_table_privilege(x.role, ('public.' || t)::regclass, 'SELECT') loop
    bad := bad || format('7. %s can read %s', r.role, r.t);
  end loop;
  for r in select p.oid::regprocedure::text as f, coalesce(array_to_string(p.proconfig, ','), 'none') as cfg from pg_proc p
           where p.pronamespace = 'public'::regnamespace and p.prosecdef
             and (p.proconfig is null or p.proconfig @> array['search_path=public']
                  or not exists (select 1 from unnest(p.proconfig) c where c like 'search_path=%')) loop
    bad := bad || format('8. privileged %s has search_path %s', r.f, r.cfg);
  end loop;
  for r in select c.relname from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r'
             and not exists (select 1 from pg_trigger g join pg_proc p on p.oid = g.tgfoid
                             where g.tgrelid = c.oid and p.proname = 'refuse_record_deletion') loop
    bad := bad || format('9. table %s can be deleted from', r.relname);
  end loop;
  for r in select c.relname from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'v'
             and not coalesce(c.reloptions @> array['security_invoker=true'], false) loop
    bad := bad || format('10. view %s does not read as the caller', r.relname);
  end loop;
  if array_length(bad, 1) > 0 then
    raise exception E'Hope Kitchen security check FAILED (% problems):\n%', array_length(bad, 1), array_to_string(bad, E'\n');
  end if;
  raise notice 'Hope Kitchen security check passed';
end $check$;

select 'security check passed' as security_check;

commit;

select 'Hope Kitchen schema ' || public.hk_schema_version() || ' installed, security check passed' as result;
